package me.eiakoji.wiki.eip.foundations;

import java.time.Duration;
import java.util.Optional;
import java.util.concurrent.*;

public class VerifyFoundations {

    public static class SynchronousRpcWorkerPool {
        private final Semaphore workerSlots;
        private final int maxThreads;
        private final Duration timeout;

        public SynchronousRpcWorkerPool(int maxThreads, Duration timeout) {
            this.maxThreads = maxThreads;
            this.workerSlots = new Semaphore(maxThreads);
            this.timeout = timeout;
        }

        public record CallResult<T>(Optional<T> data, Optional<String> error) {}

        public <T> CallResult<T> invoke(Callable<T> remoteCall) {
            if (!workerSlots.tryAcquire()) {
                return new CallResult<>(Optional.empty(),
                    Optional.of("THREAD_POOL_EXHAUSTION: Active workers at capacity (" + maxThreads + ")"));
            }

            try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
                Future<T> future = executor.submit(remoteCall);
                T data = future.get(timeout.toMillis(), TimeUnit.MILLISECONDS);
                return new CallResult<>(Optional.of(data), Optional.empty());
            } catch (TimeoutException e) {
                return new CallResult<>(Optional.empty(), Optional.of("RPC_TIMEOUT: Call exceeded " + timeout.toMillis() + "ms"));
            } catch (Exception e) {
                return new CallResult<>(Optional.empty(), Optional.of(e.getMessage()));
            } finally {
                workerSlots.release();
            }
        }
    }

    @FunctionalInterface
    public interface Filter<TIn, TOut> {
        TOut process(TIn input) throws Exception;
    }

    public static class BoundedPipe<T> {
        private final BlockingQueue<T> queue;

        public BoundedPipe(int capacity) {
            this.queue = new ArrayBlockingQueue<>(capacity);
        }

        public boolean push(T item) {
            return queue.offer(item);
        }

        public Optional<T> pull() {
            return Optional.ofNullable(queue.poll());
        }

        public int size() {
            return queue.size();
        }
    }

    public record PipelineStage<TIn, TOut>(
        String stageName,
        Filter<TIn, TOut> filter,
        BoundedPipe<TIn> inPipe,
        BoundedPipe<TOut> outPipe
    ) {
        public boolean step() throws Exception {
            Optional<TIn> input = inPipe.pull();
            if (input.isEmpty()) {
                return false;
            }
            TOut output = filter.process(input.get());
            return outPipe.push(output);
        }
    }
}
